#!/usr/bin/env bash
# Usage: commit_req.sh <slug>
# Stages all work, writes requirement_patches/<slug>.diff containing only the
# real source changes (never the patch files themselves), then commits both.
set -euo pipefail
slug="$1"
cd /workspace
git add -A
git diff --cached -- . ':(exclude)requirement_patches' > "requirement_patches/${slug}.diff"
if [ ! -s "requirement_patches/${slug}.diff" ]; then
  echo "ERROR: empty patch for ${slug}" >&2
  exit 1
fi
git add -A
git commit -q -m "impl: ${slug}"
wc -c "requirement_patches/${slug}.diff"
const path = require('path');
const base = require('../test/ut/jest.config.cjs');

module.exports = Object.assign({}, base, {
    rootDir: path.resolve(__dirname, '..'),
    collectCoverage: false,
    setupFiles: [
        'jest-canvas-mock',
        '<rootDir>/test/ut/core/setup.ts'
    ],
    setupFilesAfterEnv: [
        '<rootDir>/test/ut/core/extendExpect.ts'
    ],
    globals: {
        '__DEV__': true,
        'ts-jest': {
            tsconfig: '<rootDir>/test/ut/tsconfig.json',
            diagnostics: false,
            isolatedModules: true
        }
    },
    testMatch: [
        '<rootDir>/agent_tests/**/*.test.ts'
    ],
    moduleNameMapper: {
        '^@/(.*)$': '<rootDir>/$1'
    }
});

