            const handler = zr.handler;
            const zrViewportRoot = zr.painter.getViewportRoot();
            normalizeEvent(zrViewportRoot, e as ZRRawEvent, true);
            handler.dispatch('mousemove', e);
        }
    };
    this._onMouseLeave = function () {
        // set `_inContent` to `false` before `hideLater`
        self._inContent = false;

        if (self._enterable) {
            if (self._show) {
                self.hideLater(self._hideDelay);
            }
        }
    };

    el.addEventListener('mouseenter', this._onMouseEnter);
    el.addEventListener('mousemove', this._onMouseMove);
    el.addEventListener('mouseleave', this._onMouseLeave);
}

private _unbindEventListeners() {
    const el = this.el;
    if (el) {
        this._onMouseEnter && el.removeEventListener('mouseenter', this._onMouseEnter);
        this._onMouseMove && el.removeEventListener('mousemove', this._onMouseMove);
        this._onMouseLeave && el.removeEventListener('mouseleave', this._onMouseLeave);
    }
    this._onMouseEnter = this._onMouseMove = this._onMouseLeave = null;
}

