import { createChart } from '../test/ut/core/utHelper';
import { EChartsType } from '@/src/echarts';

function findPolygon(el: any): any {
    let found: any = null;
    el.traverse(function (child: any) {
        if (!found && child.type === 'ec-polygon') {
            found = child;
        }
    });
    return found;
}

describe('line areaStyle with empty string dimension name', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        chart.dispose();
    });

    it('builds a valid area polygon when a dataset dimension is named ""', function () {
        expect(function () {
            chart.setOption({
                animation: false,
                dataset: {
                    dimensions: ['cat', ''],
                    source: [
                        ['a', 10],
                        ['b', 20],
                        ['c', 15]
                    ]
                },
                xAxis: {type: 'category'},
                yAxis: {type: 'value'},
                series: [{
                    type: 'line',
                    areaStyle: {}
                }]
            });
        }).not.toThrow();

        const polygon = findPolygon((chart as any).getZr().storage.getRoots()[0].parent
            || (chart as any).getZr().storage.getRoots()[0]);
        expect(polygon).not.toBeNull();
        const shape = polygon.shape;
        // The stacked-on baseline must exist and match the top line point count,
        // otherwise the area path degenerates into NaN coordinates.
        expect(shape.stackedOnPoints.length).toBe(shape.points.length);
        for (let i = 0; i < shape.stackedOnPoints.length; i++) {
            expect(isNaN(shape.stackedOnPoints[i])).toBe(false);
        }
    });
});

