import { createChart } from '../test/ut/core/utHelper';
import { EChartsType } from '@/src/echarts';

describe('parallel axis extent', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        chart.dispose();
    });

    it('expands the axis extent for later series with larger values', function () {
        chart.setOption({
            parallelAxis: [
                {dim: 0, name: 'a'},
                {dim: 1, name: 'b'}
            ],
            series: [{
                type: 'parallel',
                data: [[1, 1], [2, 2]]
            }, {
                type: 'parallel',
                data: [[500, 900], [10, 20]]
            }]
        });

        const axisModel = (chart as any).getModel().getComponent('parallelAxis', 0);
        const extent = axisModel.axis.scale.getExtent();
        expect(extent[1]).toBeGreaterThanOrEqual(500);

        const axisModel1 = (chart as any).getModel().getComponent('parallelAxis', 1);
        const extent1 = axisModel1.axis.scale.getExtent();
        expect(extent1[1]).toBeGreaterThanOrEqual(900);
    });
});

