import { createChart } from '../test/ut/core/utHelper';
import { EChartsType } from '@/src/echarts';

function findRootLabel(chart: EChartsType): any {
    let found: any = null;
    const roots = (chart as any).getZr().storage.getRoots();
    for (let i = 0; i < roots.length; i++) {
        roots[i].traverse && roots[i].traverse(function (el: any) {
            if (!found && el.type === 'sector') {
                const text = el.getTextContent && el.getTextContent();
                if (text && text.style && text.style.text === 'root') {
                    found = text;
                }
            }
        });
    }
    return found;
}

function makeOption(extra: any) {
    return Object.assign({
        animation: false,
        series: [Object.assign({
            type: 'sunburst',
            center: ['50%', '50%'],
            radius: [0, '90%'],
            data: [{
                name: 'root',
                children: [
                    {name: 'a', value: 12},
                    {name: 'b', value: 13}
                ]
            }]
        }, extra)]
    });
}

describe('sunburst root label centering', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        chart.dispose();
    });

    it('centers the full circle root label despite floating point angle error', function () {
        chart.setOption(makeOption({}));
        const label = findRootLabel(chart);
        expect(label).not.toBeNull();
        const cx = (chart as any).getWidth() / 2;
        const cy = (chart as any).getHeight() / 2;
        expect(label.x).toBe(cx);
        expect(label.y).toBe(cy);
    });

    it('centers the full circle root label for counter-clockwise layout', function () {
        chart.setOption(makeOption({clockwise: false}));
        const label = findRootLabel(chart);
        expect(label).not.toBeNull();
        const cx = (chart as any).getWidth() / 2;
        const cy = (chart as any).getHeight() / 2;
        expect(label.x).toBe(cx);
        expect(label.y).toBe(cy);
    });
});

