import { createChart } from '../test/ut/core/utHelper';
import { EChartsType } from '@/src/echarts';

function findGuideLines(chart: EChartsType): any[] {
    const found: any[] = [];
    const roots = (chart as any).getZr().storage.getRoots();
    for (let i = 0; i < roots.length; i++) {
        roots[i].traverse && roots[i].traverse(function (el: any) {
            const guide = el.getTextGuideLine && el.getTextGuideLine();
            if (guide) {
                found.push(guide);
            }
        });
    }
    return found;
}

describe('labelLine smooth reset', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        chart.dispose();
    });

    function setSmooth(smooth: number | boolean) {
        chart.setOption({
            animation: false,
            series: [{
                type: 'pie',
                radius: ['0%', '40%'],
                data: [
                    {name: 'a', value: 10},
                    {name: 'b', value: 20},
                    {name: 'c', value: 30}
                ],
                label: {position: 'outside'},
                labelLine: {show: true, smooth: smooth}
            }]
        });
    }

    it('resets shape.smooth when smooth goes back to 0 / false', function () {
        setSmooth(0.6);
        let guides = findGuideLines(chart);
        expect(guides.length).toBeGreaterThan(0);
        expect(guides[0].shape.smooth).toBe(0.6);

        setSmooth(0);
        guides = findGuideLines(chart);
        expect(guides[0].shape.smooth).toBe(0);

        setSmooth(true);
        guides = findGuideLines(chart);
        expect(guides[0].shape.smooth).toBe(0.3);

        setSmooth(false);
        guides = findGuideLines(chart);
        expect(guides[0].shape.smooth).toBe(0);
    });
});

