/**
 * Decide which side is "outside" for a rect bar label.
 *
 * The sign of the bar's width/height normally tells the direction the bar grows
 * to. When the bar size is 0 that sign carries no information, so fall back to
 * the value axis direction (taking `inverse` into account) instead of blindly
 * using the positive side, which would place the label on the wrong side.
 */
function getRectLabelPositionOutside(
    layout: RectLayout,
    isBaseAxisHorizontal: boolean,
    seriesModel: BarSeriesModel
): 'top' | 'bottom' | 'left' | 'right' {
    const size = isBaseAxisHorizontal ? layout.height : layout.width;

    if (size !== 0 && !isNaN(size)) {
        return isBaseAxisHorizontal
            ? (size > 0 ? 'bottom' : 'top')
            : (size > 0 ? 'right' : 'left');
    }

    const coordSys = seriesModel.coordinateSystem as Cartesian2D;
    const baseAxis = coordSys && coordSys.getBaseAxis && coordSys.getBaseAxis() as Axis2D;
    const valueAxis = baseAxis && coordSys.getOtherAxis && coordSys.getOtherAxis(baseAxis);
    const valueAxisInverse = !!(valueAxis && valueAxis.inverse);

    return isBaseAxisHorizontal
        ? (valueAxisInverse ? 'bottom' : 'top')
        : (valueAxisInverse ? 'left' : 'right');
}

