import { createChart } from '../test/ut/core/utHelper';
import { EChartsType } from '@/src/echarts';

function getSliderView(chart: EChartsType): any {
    const views = (chart as any)._componentsViews;
    for (let i = 0; i < views.length; i++) {
        if (views[i].type === 'dataZoom.slider') {
            return views[i];
        }
    }
    return null;
}

describe('slider dataZoom with a single data point', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        chart.dispose();
    });

    it('positions the slider group at finite coordinates on a time axis', function () {
        chart.setOption({
            animation: false,
            xAxis: {type: 'time'},
            yAxis: {type: 'value'},
            dataZoom: [{type: 'slider'}],
            series: [{
                type: 'line',
                data: [['2020-01-01', 10]]
            }]
        });

        const view = getSliderView(chart);
        expect(view).not.toBeNull();
        expect(isNaN(view.group.x)).toBe(false);
        expect(isNaN(view.group.y)).toBe(false);

        const pts = view._shadowPolygonPts as number[][];
        for (let i = 0; i < pts.length; i++) {
            expect(isNaN(pts[i][0])).toBe(false);
            expect(isNaN(pts[i][1])).toBe(false);
        }
    });

    it('positions the slider the same way as with multiple points', function () {
        chart.setOption({
            animation: false,
            xAxis: {type: 'time'},
            yAxis: {type: 'value'},
            dataZoom: [{type: 'slider'}],
            series: [{
                type: 'line',
                data: [['2020-01-01', 10], ['2020-01-02', 20]]
            }]
        });
        const multiView = getSliderView(chart);
        const expectedX = multiView.group.x;
        const expectedY = multiView.group.y;

        chart.setOption({
            series: [{
                type: 'line',
                data: [['2020-01-01', 10]]
            }]
        }, {replaceMerge: ['series']});

        const view = getSliderView(chart);
        expect(view.group.x).toBe(expectedX);
        expect(view.group.y).toBe(expectedY);
    });
});

