import { createChart } from '../test/ut/core/utHelper';
import { EChartsType } from '@/src/echarts';

function collectProgressFills(chart: EChartsType): string[] {
    const fills: string[] = [];
    const roots = (chart as any).getZr().storage.getRoots();
    for (let i = 0; i < roots.length; i++) {
        roots[i].traverse && roots[i].traverse(function (el: any) {
            if (el.type === 'sector' && el.__progress) {
                fills.push(el.style.fill);
            }
        });
    }
    return fills;
}

function makeOption(progress: any) {
    return {
        animation: false,
        series: [{
            type: 'gauge',
            min: 0,
            max: 100,
            axisLine: {
                lineStyle: {
                    color: [[0.3, '#ff0000'], [0.7, '#00ff00'], [1, '#0000ff']]
                }
            },
            progress: progress,
            data: [{value: 50}]
        }]
    };
}

describe('gauge progress.color auto', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        chart.dispose();
    });

    function getProgressFill(): string {
        let fill: string = null;
        const views = (chart as any)._chartsViews;
        const progressEls = views[0]._progressEls;
        expect(progressEls && progressEls.length).toBeTruthy();
        fill = progressEls[0].style.fill;
        return fill;
    }

    it('itemStyle.color: "auto" follows the axisLine color mapping', function () {
        chart.setOption(makeOption({show: true, itemStyle: {color: 'auto'}}));
        // value 50 of [0, 100] -> 0.5 -> second color stop
        expect(getProgressFill()).toBe('#00ff00');
    });

    it('progress.color: "auto" follows the axisLine color mapping', function () {
        chart.setOption(makeOption({show: true, color: 'auto'}));
        expect(getProgressFill()).toBe('#00ff00');
    });

    it('an explicit color is still honored', function () {
        chart.setOption(makeOption({show: true, itemStyle: {color: '#123456'}}));
        expect(getProgressFill()).toBe('#123456');
    });

    it('follows the series color by default', function () {
        chart.setOption(makeOption({show: true}));
        expect(getProgressFill()).not.toBe('auto');
        expect(getProgressFill()).toBeTruthy();
    });
});

