import EffectLine from '@/src/chart/helper/EffectLine';
import EffectPolyline from '@/src/chart/helper/EffectPolyline';

type AnyEffectLine = EffectLine & Record<string, any>;

function makeEffectLine(roundTrip: boolean): AnyEffectLine {
    const line = Object.create(EffectLine.prototype) as AnyEffectLine;
    line._roundTrip = roundTrip;
    line._symbolType = 'circle';
    line._symbolScale = [1, 1];
    return line;
}

function makeSymbol(t: number) {
    return {
        __t: t,
        __p1: [0, 0],
        __p2: [100, 0],
        __cp1: [50, 0],
        x: 0,
        y: 0
    } as any;
}

describe('lines effect symbol orientation at loop end', function () {

    it('keeps the forward rotation at __t === 1 when roundTrip is off', function () {
        const line = makeEffectLine(false);
        const mid = makeSymbol(0.5);
        line._updateSymbolPosition(mid);
        const forwardRotation = mid.rotation;

        const end = makeSymbol(1);
        line._updateSymbolPosition(end);
        expect(end.rotation).toBe(forwardRotation);
    });

    it('still reverses at __t >= 1 when roundTrip is on', function () {
        const line = makeEffectLine(true);
        const mid = makeSymbol(0.5);
        line._updateSymbolPosition(mid);
        const forwardRotation = mid.rotation;

        const back = makeSymbol(1.5);
        line._updateSymbolPosition(back);
        expect(back.rotation).not.toBe(forwardRotation);
    });

    it('polyline keeps the forward rotation at __t === 1 when roundTrip is off', function () {
        const line = Object.create(EffectPolyline.prototype) as AnyEffectLine;
        line._roundTrip = false;
        line._points = [[0, 0], [50, 0], [100, 0]];
        line._offsets = [0, 0.5, 1];
        line._length = 100;
        line._lastFrame = 0;
        line._lastFramePercent = 0;

        const mid = makeSymbol(0.25);
        line._updateSymbolPosition(mid);
        const forwardRotation = mid.rotation;

        const end = makeSymbol(1);
        line._updateSymbolPosition(end);
        expect(end.rotation).toBe(forwardRotation);
    });

    it('polyline still reverses at __t > 1 when roundTrip is on', function () {
        const line = Object.create(EffectPolyline.prototype) as AnyEffectLine;
        line._roundTrip = true;
        line._points = [[0, 0], [50, 0], [100, 0]];
        line._offsets = [0, 0.5, 1];
        line._length = 100;
        line._lastFrame = 0;
        line._lastFramePercent = 0;

        const mid = makeSymbol(0.25);
        line._updateSymbolPosition(mid);
        const forwardRotation = mid.rotation;

        const back = makeSymbol(1.5);
        line._updateSymbolPosition(back);
        expect(back.rotation).not.toBe(forwardRotation);
    });
});

