                this.renderSeries(seriesModel, markerModel, ecModel, api);
                // Each series owns its own marker model, so `z`/`zlevel` has to be
                // applied per series here. The global auto-z pass only knows the
                // shared marker component model (see `preventAutoZ` on MarkerModel).
                const markerDraw = markerGroupMap.get(seriesModel.id);
