import { makeInner } from '../../util/model';
import SeriesModel from '../../model/Series';
import Group from 'zrender/src/graphic/Group';
import { enterBlur, leaveBlur } from '../../util/states';
import { retrieveZInfo, traverseUpdateZ } from '../../util/graphic';

const inner = makeInner<{
    keep: boolean
}, MarkerDraw>();

interface MarkerDraw {
    group: Group
}
abstract class MarkerView extends ComponentView {

    static type = 'marker';
    type = MarkerView.type;

    /**
     * Markline grouped by series
     */
    markerGroupMap: HashMap<MarkerDraw>;

    init() {
        this.markerGroupMap = createHashMap();
    }

    render(markerModel: MarkerModel, ecModel: GlobalModel, api: ExtensionAPI) {
        const markerGroupMap = this.markerGroupMap;
        markerGroupMap.each(function (item) {
            inner(item).keep = false;
        });

        ecModel.eachSeries(seriesModel => {
            const markerModel = MarkerModel.getMarkerModelFromSeries(
                seriesModel,
                this.type as 'markPoint' | 'markLine' | 'markArea'
            );
            if (markerModel) {
                this.renderSeries(seriesModel, markerModel, ecModel, api);
                // Each series owns its own marker model, so `z`/`zlevel` has to be
                // applied per series here. The global auto-z pass only knows the
                // shared marker component model (see `preventAutoZ` on MarkerModel).
                const markerDraw = markerGroupMap.get(seriesModel.id);
                if (markerDraw) {
                    const zInfo = retrieveZInfo(markerModel);
                    traverseUpdateZ(markerDraw.group, zInfo.z, zInfo.zlevel);
                }
            }
        });

        markerGroupMap.each(item => {
            !inner(item).keep && this.group.remove(item.group);
        });
    }

